// Per-pane token + cost telemetry (#1181). Reads the latest rollup keyed by pane id — each pane's
// latest Claude transcript parsed for its `usage` totals AND its `message.model`. Feeds two surfaces:
// the header model pill's "actual running model" (so it reflects what the CLI is really running, not
// just the configured model) and the Telemetry · cost view.
//
// IN-PROCESS since #4074 (`logs_usage`), not the `bsc` bridge. #3630 moved the hot pollers off the
// bridge and left this one on it as "low-frequency" — but it polls every 4s, which made it the app's
// single biggest process spawner (415 calls in a 27-minute window). Every spawn blocked Tauri's main
// thread, so the invoke queue backed up to 25s and unrelated commands waited behind it. Same rows:
// `logs_usage` calls the same `logs::cost::usage` the CLI's `cost` verb does.
//
// ONE POLLER FOR THE WHOLE APP (#one-poller-per-datum-not-one-per-consumer). The value is a map of
// EVERY pane, built from ONE `logs_usage` call — the data is global, so polling it per consumer is
// pure duplication. It was instantiated twice: `consolepage`, and `telemetryview`, which is a PANE
// VIEW rendered once per pane showing it. So every extra Telemetry pane added another 4s poll of the
// same app-wide rollup, and that read is the most expensive one in the app — it re-parses every
// referenced Claude transcript on each call (#the-cost-rollup-reparses-every-transcript-on-every-poll).
// Measured 655 calls / 324.8s in one session.
//
// The dedupe lives INSIDE the hook so the signature is unchanged and no consumer moves — the blast
// radius stays at this module. Deliberately NOT a new Zustand key: a store field rewritten every 4s
// wakes every subscriber, and `two-store-keys-drive-more-than-half-the-apps-jank` records what that
// already costs here. A shared subscription gives the same dedupe without adding a jank source.
import { useEffect, useState } from "react";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";

/** One pane's token + cost rollup, as serialized by `bsc logs cost --full` (`logs::cost::Usage` —
 *  plain snake_case, no serde rename, so the keys match the struct). */
export interface PaneTokenUsage {
  pane: string;
  session_id: string;
  /** The model the CLI recorded in the transcript (`message.model`) — the ACTUAL running model. */
  model: string;
  input_tokens: number;
  output_tokens: number;
  cache_creation_tokens: number;
  cache_read_tokens: number;
  cost_usd: number;
}

const EMPTY: Map<string, PaneTokenUsage> = new Map();

/** How often the ONE shared poller refreshes while the rollup keeps CHANGING — the working rate,
 *  matching the coordination/CI pollers. */
const INTERVAL_MS = 4000;
/** The slowest it backs off to while the answer is unchanged (#pollers-back-off-when-a-pane-is-idle).
 *
 *  This read is the most expensive one in the app — it re-parses every referenced Claude transcript on
 *  each call — and it was 655 calls / 324.8s in one session, much of it asking a quiet app the same
 *  question. The cap bounds how late a change can be noticed: a session that starts working is seen
 *  within this, then the rate snaps back to `INTERVAL_MS` on the very next tick. */
const IDLE_INTERVAL_MS = 32000;

type Listener = (m: Map<string, PaneTokenUsage>) => void;

/** Module-level, so every consumer in the process shares one interval and one in-flight invoke. */
const listeners = new Set<Listener>();
let timer: ReturnType<typeof setTimeout> | null = null;
/** The most recent rollup, replayed to a late subscriber so it renders immediately rather than
 *  waiting a full interval — mounting a Telemetry pane should not show empty for 4s. */
let latest: Map<string, PaneTokenUsage> = EMPTY;
/** The row cap the poller runs with — the largest any live consumer asked for, so one consumer's
 *  smaller limit can never truncate another's view of the same shared map. */
let activeLimit = 0;
/** Guards against a second fetch starting while one is in flight; a slow read must not stack up. */
let inFlight = false;
/** The current gap between reads — grows while nothing changes, resets the moment something does. */
let intervalMs = INTERVAL_MS;
/** A cheap signature of the last rollup, to tell "same answer" from "new answer" without deep-comparing
 *  a map on every tick. Rows are capped by `limit`, so this stays small. */
let lastSignature = "";

/** Re-arm the timer at `intervalMs`. `setInterval` cannot change its own period, so the poller uses a
 *  chained `setTimeout` — the alternative is a fixed fast interval that mostly decides to do nothing,
 *  which still wakes the main thread on every tick and is the thing being removed. */
function rearm(): void {
  if (timer) clearTimeout(timer);
  timer = setTimeout(() => void tickThenRearm(), intervalMs);
}

async function tickThenRearm(): Promise<void> {
  await fetchOnce();
  if (listeners.size > 0) rearm(); // a late unmount during the read must not resurrect the poller
}

async function fetchOnce(): Promise<void> {
  if (inFlight) return;
  inFlight = true;
  // Remember what this read asked for: a consumer wanting MORE rows can join while it is in flight,
  // and the shared map must converge on the larger limit rather than leaving that consumer with a
  // truncated view until the next tick.
  const limitUsed = activeLimit;
  try {
    const rows = await safeInvoke<PaneTokenUsage[]>("logs_usage", { limit: limitUsed }, []);
    const signature = JSON.stringify(rows ?? []);
    // UNCHANGED ⇒ ask less often. A quiet app is the common case, and this read is the app's most
    // expensive; a change resets to the working rate on the very next tick, so responsiveness while
    // something is actually happening is untouched.
    if (signature === lastSignature) {
      intervalMs = Math.min(intervalMs * 2, IDLE_INTERVAL_MS);
      return; // nothing moved: no new Map, no listener wake, no re-render
    }
    lastSignature = signature;
    intervalMs = INTERVAL_MS;
    const m = new Map<string, PaneTokenUsage>();
    for (const r of rows ?? []) m.set(r.pane, r);
    latest = m;
    for (const l of listeners) l(m);
  } finally {
    inFlight = false;
  }
  if (activeLimit > limitUsed && listeners.size > 0) await fetchOnce();
}

/**
 * Poll `logs_usage` and return the latest per-pane rollup, keyed by pane id. Errors and a missing log
 * degrade to an empty map so callers fall back to the configured model.
 *
 * Every caller shares ONE poller: mounting N consumers issues one invoke per interval, not N. The
 * poll starts with the first consumer and stops with the last, so nothing polls with nobody listening.
 */
export function usePaneTokenUsage(limit = 64): Map<string, PaneTokenUsage> {
  const [byPane, setByPane] = useState<Map<string, PaneTokenUsage>>(latest);

  useEffect(() => {
    const listener: Listener = setByPane;
    listeners.add(listener);
    // The shared poller runs at the LARGEST limit any live consumer wants. Recomputed on unmount too,
    // so a big consumer leaving does not leave the poll permanently over-fetching.
    const raised = limit > activeLimit;
    if (raised) activeLimit = limit;
    setByPane(latest); // replay, so a late mount is not blank until the next tick
    if (!timer) {
      intervalMs = INTERVAL_MS; // a fresh subscription starts at the working rate, never mid-back-off
      rearm();
      void fetchOnce(); // lead with a read rather than waiting one interval for the first value
    } else if (raised) {
      // Already polling, but for fewer rows than this consumer needs — refresh now instead of
      // showing it a truncated map for up to a full interval. `fetchOnce` folds this into the
      // in-flight read if one is running.
      void fetchOnce();
    }
    return () => {
      listeners.delete(listener);
      if (listeners.size === 0) {
        if (timer) clearTimeout(timer);
        timer = null;
        activeLimit = 0;
        intervalMs = INTERVAL_MS;
        lastSignature = "";
        // Drop the cache too: with nobody listening there is nothing refreshing it, so by the time a
        // consumer mounts again it could be arbitrarily stale — and cost is a number worth being
        // right. The first mount fetches immediately, so this costs one frame, not one interval.
        latest = EMPTY;
      }
    };
  }, [limit]);

  return byPane;
}

